// Everything the caller sent arrives under `body`.
const incoming = $input.first().json;
const body = incoming.body ?? {};

const name = (body.name ?? 'world').toString().trim();

return [
  {
    json: {
      ok: true,
      message: `Hello, ${name}!`,
      receivedAt: new Date().toISOString(),
      // Handy while wiring up a new integration: see exactly what it posted.
      echo: body,
    },
  },
];
